// Generated by `augur contracts runtime sync` from Augur templates/contract-runtime. Edit the template, then re-sync.
/**
 * Augur `contract-wrap` runtime (the module `augur.contracts.json#importFrom` resolves to).
 *
 * The wrapped function's result and exceptions pass through untouched; only the
 * verdict is appended as weaver JSONL to `contracts.jsonl` under
 * `VESTIGIUM_LOGS_DIR` (or `<cwd>/logs`). Arguments and results are never
 * recorded — they may carry credentials.
 *
 * Daily rotation: the active file holds the current day only. On the first write
 * of a new day the previous file moves to `archive/contracts-YYYY-MM-DD.jsonl`,
 * which `augur contracts report` never reads (it does not descend into
 * subfolders), and archives older than the retention window are deleted.
 * @implements SPEC-CONTRACT-RUNTIME-TEMPLATE
 */

import {
  appendFileSync,
  linkSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  renameSync,
  rmSync,
  statSync,
} from "node:fs";
import { join } from "node:path";

export type ContractVerdict = true | string | undefined;

export interface ContractSpec<A extends unknown[], R> {
  pre?: (...args: A) => ContractVerdict;
  post?: (result: Awaited<R>, ...args: A) => ContractVerdict;
  contractId: string;
  id: string;
  where: string;
}

const ACTIVE_FILE = "contracts.jsonl";
const ARCHIVE_DIR = "archive";
const RETENTION_ENV = "AUGUR_CONTRACT_LOG_RETENTION_DAYS";
const DEFAULT_RETENTION_DAYS = 7;
// The day boundary is JST (UTC+9, no DST): the operators and every LUDIARS host
// read logs on the Japanese calendar, so an archive named 2026-10-13 holds what
// they call October 13th. A UTC boundary would split their working day at 09:00.
const DAY_OFFSET_MS = 9 * 60 * 60 * 1000;
const DAY_MS = 24 * 60 * 60 * 1000;
const ARCHIVE_NAME = /^\.?contracts-(\d{4}-\d{2}-\d{2})(?:\..*)?\.(?:jsonl|part)$/;

/** Per active file, the day this process last confirmed it holds only that day. */
const confirmedDay = new Map<string, string>();

/** @implements SPEC-CONTRACT-RUNTIME-TEMPLATE */
function dayKey(epochMs: number): string {
  return new Date(epochMs + DAY_OFFSET_MS).toISOString().slice(0, 10);
}

/** @implements SPEC-CONTRACT-RUNTIME-TEMPLATE */
function retentionDays(): number {
  const raw = process.env[RETENTION_ENV];
  const parsed = raw === undefined || raw.trim() === "" ? Number.NaN : Number(raw);
  return Number.isInteger(parsed) && parsed >= 0 ? parsed : DEFAULT_RETENTION_DAYS;
}

/**
 * Move `<day>`'s file into the archive without losing lines when processes race:
 * renaming the active file is the claim (exactly one process wins, the rest see
 * ENOENT), and a hard link publishes the claimed file under its archive name only
 * if that name is free; otherwise its lines are appended to the existing archive.
 * @implements SPEC-CONTRACT-RUNTIME-TEMPLATE
 */
function archiveDay(directory: string, active: string, day: string): void {
  const archive = join(directory, ARCHIVE_DIR);
  mkdirSync(archive, { recursive: true });
  const claimed = join(archive, `.contracts-${day}.${process.pid}.${Date.now()}.part`);
  renameSync(active, claimed);
  const target = join(archive, `contracts-${day}.jsonl`);
  try {
    linkSync(claimed, target);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
    appendFileSync(target, readFileSync(claimed));
  }
  rmSync(claimed, { force: true });
}

/** @implements SPEC-CONTRACT-RUNTIME-TEMPLATE */
function pruneArchive(directory: string, today: string): void {
  // Day labels are compared as dates, so the arithmetic runs on the label itself.
  const cutoff = new Date(Date.parse(`${today}T00:00:00Z`) - retentionDays() * DAY_MS).toISOString().slice(0, 10);
  for (const name of readdirSync(join(directory, ARCHIVE_DIR))) {
    const day = ARCHIVE_NAME.exec(name)?.[1];
    if (day !== undefined && day < cutoff) rmSync(join(directory, ARCHIVE_DIR, name), { force: true });
  }
}

/** @implements SPEC-CONTRACT-RUNTIME-TEMPLATE */
function rotateIfStale(directory: string, active: string, today: string): void {
  if (confirmedDay.get(active) === today) return;
  let modified: number;
  try {
    modified = statSync(active).mtimeMs;
  } catch {
    // No active file yet: the append below creates today's.
    confirmedDay.set(active, today);
    return;
  }
  const day = dayKey(modified);
  if (day < today) {
    try {
      archiveDay(directory, active, day);
    } catch (error) {
      // ENOENT: another process rotated first. Anything else (a Windows sharing
      // violation while another writer has the file open) is retried next write.
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") return;
    }
    pruneArchive(directory, today);
  }
  confirmedDay.set(active, today);
}

/** @implements SPEC-CONTRACT-RUNTIME-TEMPLATE */
function record(message: string, context: Record<string, string>): void {
  try {
    const directory = process.env.VESTIGIUM_LOGS_DIR || join(process.cwd(), "logs");
    mkdirSync(directory, { recursive: true });
    const active = join(directory, ACTIVE_FILE);
    const now = Date.now();
    try {
      rotateIfStale(directory, active, dayKey(now));
    } catch {
      // Rotation is housekeeping; the event is still written.
    }
    appendFileSync(
      active,
      `${JSON.stringify({ time: new Date(now).toISOString(), msg: message, ctx: context })}\n`,
      "utf8",
    );
  } catch {
    // Observation must never change the wrapped operation.
  }
}

/** @implements SPEC-CONTRACT-RUNTIME-TEMPLATE */
function failure(verdict: ContractVerdict): string | null {
  if (verdict === true || verdict === undefined) return null;
  return typeof verdict === "string" ? verdict : "predicate failed";
}

/** @implements SPEC-CONTRACT-RUNTIME-TEMPLATE */
export function contract<A extends unknown[], R>(
  fn: (...args: A) => R,
  spec: ContractSpec<A, R>,
): (...args: A) => R {
  const { pre, post, contractId, id, where } = spec;
  return function contracted(this: unknown, ...args: A): R {
    const context = { contract: contractId, id, where, observed_at: new Date().toISOString() };
    let preReason: string | null = null;
    try {
      preReason = failure(pre?.(...args));
    } catch {
      record("contract predicate threw", { ...context, phase: "pre", reason: "pre predicate threw" });
    }
    if (preReason) record("contract violated", { ...context, phase: "pre", reason: preReason });

    const observe = (result: Awaited<R>): void => {
      try {
        const postReason = failure(post?.(result, ...args));
        if (postReason) record("contract violated", { ...context, phase: "post", reason: postReason });
        else if (!preReason) record("contract observed", { ...context, phase: "ok" });
      } catch {
        record("contract predicate threw", { ...context, phase: "post", reason: "post predicate threw" });
      }
    };

    const result = fn.apply(this, args);
    if (result instanceof Promise) {
      return result.then((value: Awaited<R>) => {
        observe(value);
        return value;
      }) as R;
    }
    observe(result as Awaited<R>);
    return result;
  };
}
